<?php
defined( 'ABSPATH' ) || exit;
get_header();
$entitlement = SCHA_Entitlements::current();
$sources = is_user_logged_in() ? SCHA_Corpus::accessible_catalog( $entitlement['access_class'], 200 ) : SCHA_Corpus::public_catalog( 200 );
?>
<main id="primary" class="scha-page" dir="auto"><div class="scha-shell"><?php SCHA_Public::back_home_controls(); SCHA_Public::page_header( __( 'Approved AI Sources', SCHA_TEXT_DOMAIN ), __( 'Versioned, access-labelled, rights-reviewed sources controlled by their canonical owners.', SCHA_TEXT_DOMAIN ) ); SCHA_Public::nav(); ?><section class="scha-card"><p><?php esc_html_e( 'Private clinical records, messages, identity evidence, private studies, and unrestricted web material are excluded.', SCHA_TEXT_DOMAIN ); ?></p></section><section class="scha-source-list"><?php foreach ( $sources as $source ) : ?><article class="scha-card" id="source-<?php echo esc_attr( $source['public_id'] ); ?>"><h2><?php echo esc_html( $source['title'] ); ?></h2><p><?php echo esc_html( $source['owner_file'] . ' · ' . $source['item_version'] . ' · ' . $source['language'] . ' · ' . $source['license_name'] ); ?></p><?php if ( ! empty( $source['source_url'] ) ) : ?><a class="scha-button scha-button-quiet" href="<?php echo esc_url( $source['source_url'] ); ?>" rel="noopener"><?php esc_html_e( 'Open Canonical Source', SCHA_TEXT_DOMAIN ); ?></a><?php endif; ?></article><?php endforeach; ?><?php if ( empty( $sources ) ) : ?><article class="scha-card"><h2><?php esc_html_e( 'No approved source is available', SCHA_TEXT_DOMAIN ); ?></h2></article><?php endif; ?></section></div></main><?php get_footer(); ?>
